from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
from itertools import product


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bits.get(data["source"], 0)
    limit = data["coupons"]
    start_state = (data["source"], initial_mask, 0)
    distances = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, 0)]
    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full and (coupon_rule == "at_most" or used == limit):
            return {"arrival": arrival}
        for edge in data["edges"]:
            if edge["u"] != node:
                continue
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < limit:
                discounted = max(minimum_duration, edge["duration"] - edge.get("discount", 0))
                options.append((discounted, used + 1))
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_used))
    return {"arrival": None}


def _ledger(data):
    rounding = data["rounding"]
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))

    def rounded(numerator):
        if rounding == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    options = []
    for name in names:
        versions = [None] + sorted(row["version"] for row in packages[name])
        options.append(versions)

    best_key = None
    best = None
    for values in product(*options):
        selected = {name: version for name, version in zip(names, values) if version is not None}
        rows = {name: next(row for row in packages[name] if row["version"] == version)
                for name, version in selected.items()}
        valid = True
        for name, (low, high) in roots.items():
            if name not in selected or not low <= selected[name] <= high:
                valid = False
                break
        if not valid:
            continue
        for name, version in selected.items():
            if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                valid = False
                break
        if not valid:
            continue

        graph = {name: [] for name in selected}
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                if other not in selected or not dep["min"] <= selected[other] <= dep["max"]:
                    valid = False
                    break
                graph[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in selected:
                valid = False
                break
            reachable.add(name)
            stack.extend(graph[name])
        if not valid or reachable != set(selected):
            continue

        active, finished = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in graph):
            continue

        key = tuple(selected.get(name, -1) for name in names)
        if best_key is None or key < best_key:
            best_key, best = key, selected
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    eligible = [job for job in jobs if job["id"] not in blocked]
    for chosen in _subsets(eligible, k):
        ids = [job["id"] for job in chosen]
        idset = set(ids)
        if not mandatory <= idset:
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in chosen)
        sorted_ids = sorted(ids)
        if best_value is None or value > best_value or (value == best_value and sorted_ids < best_ids):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _subsets(items, size):
    # Generate fixed-size subsets without relying on order in the input.
    n = len(items)
    if size < 0 or size > n:
        return
    indices = list(range(size))
    if size == 0:
        yield []
        return
    while True:
        yield [items[i] for i in indices]
        i = size - 1
        while i >= 0 and indices[i] == n - size + i:
            i -= 1
        if i < 0:
            return
        indices[i] += 1
        for j in range(i + 1, size):
            indices[j] = indices[j - 1] + 1


SOLVERS = {
    "component_01": lambda data: _route(data, "at_most", 2),
    "component_02": lambda data: _route(data, "exact", 2),
    "component_03": lambda data: _route(data, "at_most", 1),
    "component_04": lambda data: _route(data, "exact", 1),
    "component_05": lambda data: _route(data, "at_most", 2),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _intervals,
}
